import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class NativeChecks{
 static ClassNode cls(ZipFile z)throws Exception{var c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry("dev/zomboid/integration/Lamps.class")).readAllBytes()).accept(c,0);return c;}static MethodNode method(ClassNode c,String name){return c.methods.stream().filter(m->m.name.equals(name)).findFirst().orElseThrow();}static List<String>code(MethodNode m){List<String>out=new ArrayList<>();for(var i:m.instructions){if(i.getOpcode()<0)continue;String s=""+i.getOpcode();if(i instanceof MethodInsnNode q)s+=q.owner+q.name+q.desc;if(i instanceof FieldInsnNode q)s+=q.owner+q.name+q.desc;if(i instanceof TypeInsnNode q)s+=q.desc;if(i instanceof VarInsnNode q)s+=q.var;if(i instanceof IntInsnNode q)s+=q.operand;if(i instanceof LdcInsnNode q)s+=q.cst;out.add(s);}return out;}
 public static void main(String[]args)throws Exception{try(var z=new ZipFile(args[0]);var old=new ZipFile(args[1])){var c=cls(z);var previous=cls(old);var m=method(c,"beam");var ins=new ArrayList<AbstractInsnNode>();for(var i:m.instructions)if(i.getOpcode()>=0)ins.add(i);if(!(ins.get(0) instanceof VarInsnNode a&&a.var==0&&ins.get(1) instanceof TypeInsnNode t&&t.getOpcode()==Opcodes.INSTANCEOF&&t.desc.equals("net/minecraft/world/entity/player/Player")&&ins.get(2) instanceof JumpInsnNode jump&&jump.getOpcode()==Opcodes.IFEQ&&ins.get(3).getOpcode()==Opcodes.RETURN))throw new AssertionError("player block-light path must return before world access");int n=1;var branch=(JumpInsnNode)ins.get(2);if(branch.label.getPrevious().getOpcode()!=Opcodes.RETURN)throw new AssertionError("non-player branch crosses player early return");n++;
 var after=code(m);if(!after.subList(4,after.size()).equals(code(method(previous,"beam"))))throw new AssertionError("dropped-light path changed");n++;
 for(var other:previous.methods)if(!other.name.equals("beam")){if(!code(other).equals(code(method(c,other.name))))throw new AssertionError("unrelated lamp control changed "+other.name);n++;}
 System.out.println("NATIVE_PLAYER_NO_WORLD_LIGHT_DROPPED_LAMP_AND_KEY_CONTROL_PRESERVATION_CHECKS="+n);}}
}
